<?php
require_once __DIR__.'/../config/auth.php';check_access([1]);
require_once __DIR__.'/rapor.php';
require_once __DIR__.'/rapor_tools.php';
$db=Database::getInstance();$ready=rapor_ready($db);$adminReady=rapor_admin_ready($db);$error='';$posted=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:null;$input=$posted??$_GET;
$kelas=filter_var($input['kelas_id']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]])?:0;
$years=$db->query('SELECT DISTINCT tahun_ajaran FROM pengajaran ORDER BY tahun_ajaran DESC')->fetchAll(PDO::FETCH_COLUMN);
if($ready)$years=array_values(array_unique(array_merge($years,$db->query('SELECT DISTINCT tahun_ajaran FROM rapor ORDER BY tahun_ajaran DESC')->fetchAll(PDO::FETCH_COLUMN))));rsort($years);
$tahun=is_string($input['tahun_ajaran']??null)?$input['tahun_ajaran']:($years[0]??'');
$semester=($input['semester']??'')==='Genap'?'Genap':'Ganjil';$jenis=($input['jenis']??'')==='UAS'?'UAS':'UTS';
$context=['kelas_id'=>$kelas,'tahun_ajaran'=>$tahun,'semester'=>$semester,'jenis'=>$jenis];
if($posted){
    if(!is_string($posted['csrf_token']??null)||!verify_csrf($posted['csrf_token'])){http_response_code(403);$error='Sesi formulir tidak valid. Muat ulang halaman.';}
    elseif(!$ready)$error='Penyimpanan rapor belum tersedia.';
    else try{rapor_admin_save($db,$posted,(int)$_SESSION['user_id']);$_SESSION['rapor_admin_success']=($posted['admin_action']==='settings'?'Pengaturan rapor berhasil disimpan.':($posted['admin_action']==='lock'?'Rapor kelas dan periode ini dikunci.':'Kunci rapor kelas dan periode ini dibuka.'));header('Location: rapor.php?'.http_build_query($context));exit;}
    catch(RuntimeException $e){$error=$e instanceof PDOException?'Perubahan belum dapat disimpan. Muat ulang dan coba kembali.':$e->getMessage();if($e instanceof PDOException)error_log('Admin rapor: '.$e->getMessage());}
}
$classes=$db->query('SELECT id,nama_kelas FROM kelas ORDER BY nama_kelas')->fetchAll();$classMap=[];$summary=[];
foreach($classes as $c){$classMap[(int)$c['id']]=$c;$summary[(int)$c['id']]=['siswa'=>0,'tersimpan'=>0,'lengkap'=>0,'belum_dibuat'=>0];}
$students=$db->query('SELECT id,kelas_id,nama_lengkap FROM siswa ORDER BY nama_lengkap,id')->fetchAll();
$reports=$ready?rapor_admin_reports($db,$tahun,$semester,$jenis):[];$byClass=[];$savedStudents=[];$savedInClass=[];$archived=[];
foreach($reports as $r){$cid=(int)$r['kelas_id'];$savedStudents[(int)$r['siswa_id']]=$r;$savedInClass[$cid][(int)$r['siswa_id']]=true;if(!isset($classMap[$cid])){$archived[]=$r;continue;}$byClass[$cid][]=$r;$summary[$cid]['tersimpan']++;if($r['lengkap'])$summary[$cid]['lengkap']++;}
foreach($students as $s){$cid=(int)$s['kelas_id'];if(isset($summary[$cid])){$summary[$cid]['siswa']++;if(!isset($savedInClass[$cid][(int)$s['id']]))$summary[$cid]['belum_dibuat']++;}}
$settings=[];
if($adminReady){$q=$db->prepare('SELECT * FROM rapor_administrasi WHERE tahun_ajaran=? AND semester=? AND jenis=?');$q->execute([$tahun,$semester,$jenis]);foreach($q->fetchAll() as $a)$settings[(int)$a['kelas_id']]=$a;}
$selected=$classMap[$kelas]??null;$configuration=$settings[$kelas]??null;
$success=$_SESSION['rapor_admin_success']??'';unset($_SESSION['rapor_admin_success']);
$totals=['tersimpan'=>count($reports),'lengkap'=>count(array_filter($reports,static fn($r)=>$r['lengkap'])),'belum_dibuat'=>array_sum(array_column($summary,'belum_dibuat'))];
require __DIR__.'/header.php';require __DIR__.'/sidebar.php';
?>
