<div class="col-md-3"><label class="form-label" for="admin-year">Tahun ajaran</label><select id="admin-year" class="form-select" name="tahun_ajaran" required><?php foreach(array_unique(array_merge($years,$tahun?[$tahun]:[])) as $year): ?><option <?= $year===$tahun?'selected':'' ?>><?= sanitize($year) ?></option><?php endforeach ?></select></div>
<?php foreach(['semester'=>['Ganjil','Genap'],'jenis'=>['UTS','UAS']] as $key=>$options): ?><div class="col-md-2"><label class="form-label" for="admin-<?= $key ?>"><?= $key==='semester'?'Semester':'Jenis rapor' ?></label><select class="form-select" id="admin-<?= $key ?>" name="<?= $key ?>"><?php foreach($options as $value): ?><option <?= ($key==='semester'?$semester:$jenis)===$value?'selected':'' ?>><?= $value ?></option><?php endforeach ?></select></div><?php endforeach ?>
<div class="col-md-3"><label class="form-label" for="admin-class">Kelas</label><select id="admin-class" name="kelas_id" class="form-select"><option value="0">Semua kelas</option><?php foreach($classes as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $kelas===(int)$c['id']?'selected':'' ?>><?= sanitize($c['nama_kelas']) ?></option><?php endforeach ?></select></div><div class="col-md-2"><button class="btn btn-primary w-100"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i> Tampilkan</button></div></form></div></section>
<div class="rapor-stats"><div><strong><?= $totals['tersimpan'] ?></strong><span>Rapor tersimpan</span></div><div><strong><?= $totals['lengkap'] ?></strong><span>Isian lengkap</span></div><div><strong><?= $totals['belum_dibuat'] ?></strong><span>Belum ada rapor di kelas saat ini</span></div></div>
<p class="small text-muted">Ringkasan mencakup semua kelas pada periode terpilih. Lengkap berarti nilai/deskripsi/saran serta data penerbitan terisi, bukan persetujuan kepala sekolah. Arsip mempertahankan identitas kelas saat rapor dibuat.</p>
