<?php if($selected): require __DIR__.'/rapor_admin_settings_view.php'; endif ?>
<section class="card mb-4" data-rapor-filter><div class="card-body"><h6><i class="fa-solid fa-school" aria-hidden="true"></i> Progres per kelas</h6><?php rapor_filter_toolbar('rapor-admin-class-search','Cari kelas atau wali kelas'); ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Kelas / wali kelas</th><th>Siswa saat ini</th><th>Tersimpan</th><th>Lengkap</th><th>Perlu dilengkapi</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach($classes as $c): $cid=(int)$c['id'];if($kelas&&$kelas!==$cid)continue;$stats=$summary[$cid];$ctx=['kelas_id'=>$cid,'tahun_ajaran'=>$tahun,'semester'=>$semester,'jenis'=>$jenis];$config=$settings[$cid]??[]; ?>
<tr data-filter-row data-filter-search-value="<?= sanitize($c['nama_kelas'].' '.($config['nama_wali_kelas']??'')) ?>" data-incomplete="<?= $stats['tersimpan']>$stats['lengkap']||$stats['belum_dibuat']>0?'1':'0' ?>"><td><strong><?= sanitize($c['nama_kelas']) ?></strong><small class="d-block text-muted"><?= sanitize($config['nama_wali_kelas']??'Wali kelas belum diatur') ?></small></td><td><?= $stats['siswa'] ?></td><td><?= $stats['tersimpan'] ?></td><td><?= $stats['lengkap'] ?></td><td><?= $stats['tersimpan']-$stats['lengkap'] ?> draf<small class="d-block text-muted"><?= $stats['belum_dibuat'] ?> siswa belum memiliki rapor di kelas ini</small></td><td><span class="badge <?= !empty($config['terkunci'])?'bg-secondary':'bg-success' ?>"><?= !empty($config['terkunci'])?'Dikunci':'Aktif' ?></span></td><td><div class="rapor-admin-actions"><a class="btn btn-outline-primary btn-sm" href="rapor.php?<?= sanitize(http_build_query($ctx)) ?>#admin-class-detail"><i class="fa-solid fa-list-check" aria-hidden="true"></i> Kelola kelas</a><a class="btn btn-outline-secondary btn-sm" href="rapor_peringkat.php?<?= sanitize(http_build_query($ctx)) ?>"><i class="fa-solid fa-ranking-star" aria-hidden="true"></i> Peringkat</a><?php if($stats['tersimpan']): ?><a class="btn btn-outline-secondary btn-sm" href="rapor_cetak.php?<?= sanitize(http_build_query($ctx+['mode'=>'kelas'])) ?>"><i class="fa-solid fa-print" aria-hidden="true"></i> Cetak</a><?php endif ?></div></td></tr>
<?php endforeach ?></tbody></table></div></div></section>
<?php if($selected): ?>
<section class="card mb-4" data-rapor-filter><div class="card-body"><h6>Detail rapor <?= sanitize($selected['nama_kelas']) ?></h6><?php rapor_filter_toolbar('rapor-admin-student-search','Cari siswa'); ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Siswa</th><th>Kelengkapan</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach($byClass[$kelas]??[] as $r): ?><tr data-filter-row data-filter-search-value="<?= sanitize($r['nama_siswa']) ?>" data-incomplete="<?= $r['lengkap']?'0':'1' ?>"><td><?= sanitize($r['nama_siswa']) ?></td><td><span class="badge <?= $r['lengkap']?'bg-success':'bg-warning' ?>"><?= $r['lengkap']?'Isian lengkap':'Perlu dilengkapi' ?></span><?php if(!$r['lengkap']): ?><small class="d-block text-muted"><?php $missing=[];if(!(int)$r['jumlah_mapel'])$missing[]='Belum ada mapel';if((int)$r['mapel_belum_lengkap'])$missing[]=$r['mapel_belum_lengkap'].' mapel belum lengkap';foreach(['nama_wali_kelas'=>'Nama wali kelas','nama_kepala_sekolah'=>'Nama kepala sekolah','tempat_terbit'=>'Tempat penerbitan','tanggal_terbit'=>'Tanggal penerbitan'] as $key=>$label)if(trim((string)($r[$key]??''))==='')$missing[]=$label;echo sanitize(implode(', ',$missing)); ?></small><?php endif ?></td><td><a class="btn btn-outline-secondary btn-sm" href="rapor_cetak.php?id=<?= (int)$r['id'] ?>"><i class="fa-solid fa-eye" aria-hidden="true"></i> Periksa rapor</a></td></tr><?php endforeach ?>
<?php foreach($students as $s): if((int)$s['kelas_id']!==$kelas||isset($savedInClass[$kelas][(int)$s['id']]))continue;$otherReport=$savedStudents[(int)$s['id']]??null; ?><tr data-filter-row data-filter-search-value="<?= sanitize($s['nama_lengkap']) ?>" data-incomplete="1"><td><?= sanitize($s['nama_lengkap']) ?></td><td>Belum memiliki rapor pada kelas ini<?php if($otherReport): ?><small class="d-block text-muted">Rapor periode ini tersimpan sebagai arsip kelas <?= sanitize($otherReport['nama_kelas']) ?>.</small><?php endif ?></td><td><?php if($otherReport): ?><a class="btn btn-outline-secondary btn-sm" href="rapor_cetak.php?id=<?= (int)$otherReport['id'] ?>">Periksa arsip kelas sebelumnya</a><?php else: ?>Menunggu pengisian wali kelas<?php endif ?></td></tr><?php endforeach ?>
